        new Recipe { Id = 8, Title = "Teriyaki Salmon", Category = "Japanese", Ingredients = "Salmon fillets\nSoy sauce\nMirin\nSake\nSugar\nGinger\nSesame seeds\nSteamed rice", Steps = "1. Mix soy sauce, mirin, sake, and sugar for glaze.\n2. Pan-sear salmon skin-side down.\n3. Flip and pour teriyaki sauce over.\n4. Cook until sauce thickens and fish is done.\n5. Garnish with sesame seeds.\n6. Serve over steamed rice with vegetables.", TotalRatings = 7, RatingSum = 30 },
